using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEditor;
using FalloutPort;
public static class WeaponRosterValidation {
 static PortGame game;static PortLoadout loadout;static int index,phase;static double next;static string report;
 public static string Run(){game=UnityEngine.Object.FindAnyObjectByType<PortGame>();Application.runInBackground=true;game.menu.NewGame();loadout=game.GetComponent<PortLoadout>();game.player.Teleport(new Vector3(0,.08f,24),0);game.player.pitch=0;game.player.view.transform.localRotation=Quaternion.identity;game.player.enabled=false;index=phase=0;report="";next=0;Directory.CreateDirectory("Logs/WeaponCaptures");EditorApplication.update-=Tick;EditorApplication.update+=Tick;return "Capturing and validating "+loadout.catalog.Length+" weapons";}
 static void Tick(){if(!EditorApplication.isPlaying||!game){EditorApplication.update-=Tick;return;}if(EditorApplication.timeSinceStartup<next)return;try{if(index>=loadout.catalog.Length){game.player.enabled=true;game.menu.ShowTitle();File.WriteAllText("Logs/WeaponValidation.txt",report+"COMPLETE "+index);EditorApplication.update-=Tick;return;}var def=loadout.catalog[index];if(phase==0){loadout.Equip(def.id,true);game.player.weapon.gameObject.SetActive(true);game.player.weapon.localPosition=loadout.Hip;game.player.weapon.localRotation=def.hipRotation;phase=1;next=EditorApplication.timeSinceStartup+.2;return;}var camera=game.player.view;var rt=new RenderTexture(960,540,24);var previous=camera.targetTexture;var active=RenderTexture.active;try{camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;var tex=new Texture2D(960,540,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,960,540),0,0);tex.Apply();File.WriteAllBytes("Logs/WeaponCaptures/"+def.id+".jpg",tex.EncodeToJPG(85));UnityEngine.Object.DestroyImmediate(tex);}finally{camera.targetTexture=previous;RenderTexture.active=active;rt.Release();UnityEngine.Object.DestroyImmediate(rt);}int before=game.ammo;game.nextShot=0;game.Fire();bool free=def.stats.reloadType=="melee"||def.stats.ammo==null;foreach(var projectile in UnityEngine.Object.FindObjectsByType<PortProjectile>())UnityEngine.Object.DestroyImmediate(projectile.gameObject);foreach(var fx in UnityEngine.Object.FindObjectsByType<Transform>())if(fx.name=="Muzzle flash"||fx.name=="Bullet tracer")UnityEngine.Object.DestroyImmediate(fx.gameObject);bool ammoOk=game.ammo==before-(free?0:1);bool hasHands=game.player.weapon.Find("First person arms")!=null;report+=def.id+" equip="+(game.player.weapon!=null)+" grip="+hasHands+" ammo="+ammoOk+"\n";File.WriteAllText("Logs/WeaponValidation.txt",report);index++;phase=0;next=EditorApplication.timeSinceStartup+.1;}catch(Exception e){File.WriteAllText("Logs/WeaponValidation.txt",report+"FAILED "+e);EditorApplication.update-=Tick;game.player.enabled=true;}}
}

